// HasCiType applies the HasEdge predicate on the "ci_type" edge.
func HasCiType() predicate.ImportTemplate {
	return predicate.ImportTemplate(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CiTypeTable, CiTypeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCiTypeWith applies the HasEdge predicate on the "ci_type" edge with a given conditions (other predicates).
func HasCiTypeWith(preds ...predicate.CiType) predicate.ImportTemplate {
	return predicate.ImportTemplate(func(s *sql.Selector) {
		step := newCiTypeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasTasks applies the HasEdge predicate on the "tasks" edge.
func HasTasks() predicate.ImportTemplate {
	return predicate.ImportTemplate(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, TasksTable, TasksColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTasksWith applies the HasEdge predicate on the "tasks" edge with a given conditions (other predicates).
func HasTasksWith(preds ...predicate.ImportTask) predicate.ImportTemplate {
	return predicate.ImportTemplate(func(s *sql.Selector) {
		step := newTasksStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ImportTemplate) predicate.ImportTemplate {
	return predicate.ImportTemplate(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ImportTemplate) predicate.ImportTemplate {
	return predicate.ImportTemplate(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ImportTemplate) predicate.ImportTemplate {
	return predicate.ImportTemplate(sql.NotPredicates(p))
}
